def report(name, value):
    print(f"{name}: {value}")
    return value

def area_circle(r):
    pi = 3.14159
    return report("circle", pi * r * r)

def area_square(s):
    return report("square", s * s)

def area_triangle(b, h):
    return report("triangle", 0.5 * b * h)

area_circle(2)
area_square(3)
area_triangle(4, 5)
